const makeQuestions = (items, firstId, bolim) => items.map(
  ([mavzu, qiyinlik, savol, answer, wrong1, wrong2, izoh], index) => {
    const togriJavob = index % 3
    const variantlar = [wrong1, wrong2]
    variantlar.splice(togriJavob, 0, answer)

    return {
      id: firstId + index,
      sinf: 7,
      bolim,
      mavzu,
      qiyinlik,
      savol,
      variantlar: variantlar.map((variant, optionIndex) => `${String.fromCharCode(65 + optionIndex)}) ${variant}`),
      togriJavob,
      izoh
    }
  }
)

